        move.b  d0,$700(a0)                     ; 57194
l_57198:
        tst.b   (LinkTimerRunning).l            ; 57198
        bne.w   l_57198                         ; 5719E
        movea.l (a7)+,a0                        ; 571A2
        move.w  (a7)+,d0                        ; 571A4
