;-------------------------------------------------------------------------------
; RollPointXY - d1: a point's screen x, y turned by the roll (the matrix's $20, $22) and
; centred ($80)
;-------------------------------------------------------------------------------
RollPointXY:
        move.w  (a5,d1.w),d5                    ; 6252A
        move.w  (a4,d1.w),d4                    ; 6252E
        tst.w   $20(a3)                         ; (enhanced) the car level (no roll: $20 = 0, $22 = $7FFF -
        bne.s   .roll                           ; most frames on a flat track): the 4 muls' result without
        cmpi.w  #$7fff,$22(a3)                  ; them. (x * $7FFF * 2) >> 16 is x - 1 for x > 0, else x;
        bne.s   .roll                           ; the registers as the release leaves them (d0's high word
        moveq   #0,d3                           ; the low word of y * $7FFF * 2: -2y; d3 0)
        move.w  d5,d0
        ble.s   .x
        subq.w  #1,d0
.x:     asr.w   #2,d0
        addi.w  #$80,d0
        move.w  d0,(a5,d1.w)
        move.w  d4,d0
        neg.w   d0
        add.w   d0,d0
        swap    d0
        move.w  d4,d0
        ble.s   .y
        subq.w  #1,d0
.y:     asr.w   #2,d0
        addi.w  #$40,d0
        move.w  d0,(a4,d1.w)
        rts
.roll:
        move.w  $22(a3),d0                      ; 62532
        muls.w  d5,d0                           ; 62536
        asl.l   #$1,d0                          ; 62538
        swap    d0                              ; 6253A
        move.w  $20(a3),d3                      ; 6253C
        muls.w  d4,d3                           ; 62540
        asl.l   #$1,d3                          ; 62542
        swap    d3                              ; 62544
        add.w   d3,d0                           ; 62546
        asr.w   #$2,d0                          ; 62548
        addi.w  #$80,d0                         ; 6254A
        move.w  d0,(a5,d1.w)                    ; 6254E
        move.w  $22(a3),d0                      ; 62552
        muls.w  d4,d0                           ; 62556
        asl.l   #$1,d0                          ; 62558
        swap    d0                              ; 6255A
        move.w  $20(a3),d3                      ; 6255C
        muls.w  d5,d3                           ; 62560
        asl.l   #$1,d3                          ; 62562
        swap    d3                              ; 62564
        sub.w   d3,d0                           ; 62566
        asr.w   #$2,d0                          ; 62568
        addi.w  #$40,d0                         ; 6256A
        move.w  d0,(a4,d1.w)                    ; 6256E
l_62572:
        rts                                     ; 62572

