        bne.s   .rys
        bra.s   .tail
.left:  cmp.w   d2,d1
        blt.s   .leftY
        move.w  d1,d3                           ; x-major, leftwards (l_66F1C)
        lsr.w   #$1,d3
        not.w   d3
        cmpi.w  #SCAN_SHORT,d1
        bcs.s   .lx
        bsr.w   ScanXMajor
        bra.s   .tail
.lxs:   subq.w  #$1,d4
        add.w   d2,d3
        bcc.s   .lx
        sub.w   d1,d3
        subq.w  #$1,d5
        move.w  d4,(a0)+
.lx:    cmp.w   d6,d4
        bne.s   .lxs
        bra.s   .tail
.leftY: move.w  d2,d3                           ; y-major, leftwards (l_66F76)
        lsr.w   #$1,d3
        not.w   d3
        bra.s   .ly
.lys:   subq.w  #$1,d5
        move.w  d4,(a0)+
