;-------------------------------------------------------------------------------
; EdgeFlush - (enhanced) DrawEdgeLine's run on a line written: x d1 to d7 on the line at a6, in
; the colour of the PlotWord at a5 (16 bytes a colour from l_66476), a word at a time. The run
; is emptied. d0, d3, a1, a4 used; the line's registers (d2, d4) kept
;-------------------------------------------------------------------------------
EdgeFlush:
        cmp.w   d1,d7
        blt.s   .none
        movea.l d2,a1
        move.l  d4,d3
        move.w  d1,d0
        lsr.w   #4,d0
        add.w   d0,d0
        lea.l   (a6,d0.w),a4                    ; the run's first word
        moveq   #-1,d4
        move.w  d1,d0
        andi.w  #$f,d0
        lsr.w   d0,d4                           ; its mask: from the run's first pixel
        move.w  d7,d0
        lsr.w   #4,d0
        move.w  d1,d2
        lsr.w   #4,d2
        sub.w   d2,d0                           ; the words after the first
        beq.s   .one
        move.w  d4,d2
        not.w   d2
        jsr     (a5)                            ; the first
        subq.w  #1,d0
        beq.s   .last
        moveq   #-1,d4
        moveq   #0,d2
.whole: jsr     (a5)                            ; the whole words
        subq.w  #1,d0
        bne.s   .whole
.last:  moveq   #-1,d4
        bra.s   .end
.one:   moveq   #-1,d2                          ; one word: both ends masked
        move.w  d7,d0
        andi.w  #$f,d0
        eori.w  #$f,d0
        lsl.w   d0,d2
        and.w   d2,d4
        bra.s   .put
.end:   move.w  d7,d0                           ; the last: to the run's last pixel
        andi.w  #$f,d0
        eori.w  #$f,d0
        lsl.w   d0,d4
.put:   move.w  d4,d2
        not.w   d2
        jsr     (a5)
        move.l  d3,d4
        move.l  a1,d2
        move.w  #$7fff,d1
        moveq   #-1,d7
.none:  rts

